import sys
from datetime import date, timedelta, datetime


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def clock(total):
    return f"{total // 60:02d}:{total % 60:02d}"


def parse_line(line):
    parts = line.split()
    if not parts:
        return None
    if parts[0] == "busy":
        return ("busy", parts[1], parts[2], parts[3], parts[4])
    elif parts[0] == "days":
        return ("days", parts[1], parts[2])
    elif parts[0] == "hours":
        return ("hours", parts[1], parts[2])
    elif parts[0] == "duration":
        return ("duration", parts[1])
    elif parts[0] == "buffer":
        return ("buffer", parts[1])
    return None


def main():
    settings = {}
    busy = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parsed = parse_line(line)
        if parsed is None:
            continue
        key, *args = parsed
        if key == "days":
            settings["days"] = [date.fromisoformat(args[0]), date.fromisoformat(args[1])]
        elif key == "hours":
            settings["hours"] = [args[0], args[1]]
        elif key == "duration":
            settings["duration"] = [int(args[0])]
        elif key == "buffer":
            settings["buffer"] = [int(args[0])] if args else [0]
        elif key == "busy":
            who, day_str, start_str, end_str = args
            day = date.fromisoformat(day_str)
            start = minutes(start_str)
            end = minutes(end_str)
            busy.setdefault((who, day.isoformat()), []).append((start, end))

    first = settings["days"][0]
    last = settings["days"][1]
    open_at, close_at = (minutes(t) for t in settings["hours"])
    need = int(settings["duration"][0])
    buffer = int(settings["buffer"][0]) if settings.get("buffer") else 0

    day = first
    while day <= last:
        day_str = day.isoformat()
        taken = []
        if ("A", day_str) in busy:
            taken.extend(busy[("A", day_str)])
        if ("B", day_str) in busy:
            taken.extend(busy[("B", day_str)])

        if day.weekday() >= 5:  # skip weekends
            day += timedelta(days=1)
            continue

        sorted_taken = sorted(taken, key=lambda x: x[0])
        free_slots = []
        cursor = open_at
        for start, end in sorted_taken:
            if cursor < start:
                if end - cursor >= need:
                    free_slots.append((clock(cursor), clock(end)))
            cursor = end

        if close_at - cursor >= need:
            free_slots.append((clock(cursor), clock(close_at)))

        formatted_slots = [f"{slot[0]}-{slot[1]}" for slot in free_slots]
        print(f"{day_str} {' '.join(formatted_slots) if formatted_slots else 'none'}")
        day += timedelta(days=1)


if __name__ == "__main__":
    main()
